join_squad:
CREATE OR REPLACE FUNCTION public.join_squad(p_squad uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); n int;
begin
  if uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  if not exists (select 1 from squads where id = p_squad) then
    return jsonb_build_object('ok', false, 'error', 'Squad not found.'); end if;
  if exists (select 1 from squad_members where user_id = uid) then
    return jsonb_build_object('ok', false, 'error', 'You are already in a squad. Leave it first.'); end if;
  select count(*) into n from squad_members where squad_id = p_squad;
  if n >= 6 then return jsonb_build_object('ok', false, 'error', 'This squad is full (6 players max).'); end if;
  insert into squad_members (squad_id, user_id, role) values (p_squad, uid, 'member');
  return jsonb_build_object('ok', true);
end $function$

leave_squad:
CREATE OR REPLACE FUNCTION public.leave_squad()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); r text;
begin
  if uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select role into r from squad_members where user_id = uid;
  if r is null then return jsonb_build_object('ok', false, 'error', 'You are not in a squad.'); end if;
  if r = 'captain' then return jsonb_build_object('ok', false, 'error', 'Captains cannot leave. Disband the squad instead.'); end if;
  delete from squad_members where user_id = uid;
  return jsonb_build_object('ok', true);
end $function$

disband_squad:
CREATE OR REPLACE FUNCTION public.disband_squad(p_squad uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid();
begin
  if uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  if not (is_admin() or exists (select 1 from squads where id = p_squad and captain = uid)) then
    return jsonb_build_object('ok', false, 'error', 'Only the captain or an admin can disband this squad.'); end if;
  delete from squads where id = p_squad;
  return jsonb_build_object('ok', true);
end $function$

