create_squad:
CREATE OR REPLACE FUNCTION public.create_squad(p_name text, p_tag text DEFAULT NULL::text, p_bio text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); sid uuid; nm text := trim(coalesce(p_name, ''));
begin
  if uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  if not exists (select 1 from squad_creators where user_id = uid) then
    return jsonb_build_object('ok', false, 'error', 'Only approved creators can create a squad. Request creator access below.'); end if;
  if exists (select 1 from squad_members where user_id = uid) then
    return jsonb_build_object('ok', false, 'error', 'You are already in a squad. Leave it first.'); end if;
  if char_length(nm) < 3 or char_length(nm) > 30 then
    return jsonb_build_object('ok', false, 'error', 'Squad name must be 3-30 characters.'); end if;
  if exists (select 1 from squads where lower(name) = lower(nm)) then
    return jsonb_build_object('ok', false, 'error', 'That squad name is taken.'); end if;
  insert into squads (name, tag, bio, captain) values (nm, nullif(trim(coalesce(p_tag, '')), ''), nullif(left(coalesce(p_bio, ''), 200), ''), uid) returning id into sid;
  insert into squad_members (squad_id, user_id, role) values (sid, uid, 'captain');
  return jsonb_build_object('ok', true, 'id', sid, 'name', nm);
end $function$

review_task:
CREATE OR REPLACE FUNCTION public.review_task(p_completion_id bigint, p_approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); c record; t record; mem record; n int := 0;
begin
  if uid is null or not is_admin() then return jsonb_build_object('ok', false, 'error', 'Admin only.'); end if;
  select * into c from task_completions where id = p_completion_id and status = 'pending';
  if c is null then return jsonb_build_object('ok', false, 'error', 'Submission not found or already reviewed.'); end if;
  select * into t from tasks where id = c.task_id;
  update task_completions set status = case when p_approve then 'approved' else 'rejected' end, reviewed_at = now() where id = p_completion_id;
  if p_approve then
    if c.squad_id is not null then
      for mem in select user_id from squad_members where squad_id = c.squad_id loop
        insert into player_rewards (user_id, task_id, task_title, kind, points, badge) values (mem.user_id, t.id, t.title, t.kind, t.points, t.badge);
        n := n + 1;
      end loop;
    else
      insert into player_rewards (user_id, task_id, task_title, kind, points, badge) values (c.user_id, t.id, t.title, t.kind, t.points, t.badge);
      n := 1;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'approved', p_approve, 'rewarded_players', n);
end $function$

submit_task:
CREATE OR REPLACE FUNCTION public.submit_task(p_task_id bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); t record; sid uuid;
begin
  if uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select * into t from tasks where id = p_task_id and active;
  if t is null then return jsonb_build_object('ok', false, 'error', 'Task not found.'); end if;
  if exists (select 1 from task_completions where task_id = p_task_id and user_id = uid and status in ('pending','approved')) then
    return jsonb_build_object('ok', false, 'error', 'You already submitted this task.'); end if;
  if t.kind = 'team' then
    select m.squad_id into sid from squad_members m where m.user_id = uid and m.role = 'captain';
    if sid is null then return jsonb_build_object('ok', false, 'error', 'Team tasks are submitted by your squad captain.'); end if;
    if exists (select 1 from task_completions where task_id = p_task_id and squad_id = sid and status in ('pending','approved')) then
      return jsonb_build_object('ok', false, 'error', 'Your squad already submitted this task.'); end if;
    insert into task_completions (task_id, user_id, squad_id, note) values (p_task_id, uid, sid, left(coalesce(p_note,''),280));
  else
    insert into task_completions (task_id, user_id, note) values (p_task_id, uid, left(coalesce(p_note,''),280));
  end if;
  return jsonb_build_object('ok', true);
end $function$

