squad_invite:
CREATE OR REPLACE FUNCTION public.squad_invite(p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_squad uuid; v_target uuid; v_count int;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select squad_id into v_squad from public.squad_members where user_id = v_uid and role = 'captain';
  if v_squad is null then return jsonb_build_object('ok', false, 'error', 'Only the squad captain can invite players.'); end if;
  select count(*) into v_count from public.squad_members where squad_id = v_squad;
  if v_count >= 6 then return jsonb_build_object('ok', false, 'error', 'Squad is full (6 players).'); end if;
  select id into v_target from public.profiles where lower(username) = lower(trim(coalesce(p_name, ''))) or lower(ign) = lower(trim(coalesce(p_name, ''))) limit 1;
  if v_target is null then return jsonb_build_object('ok', false, 'error', 'No player with that name. They need an account first.'); end if;
  if v_target = v_uid then return jsonb_build_object('ok', false, 'error', 'You are already the captain.'); end if;
  if exists (select 1 from public.squad_members where user_id = v_target) then return jsonb_build_object('ok', false, 'error', 'That player is already in a squad.'); end if;
  if exists (select 1 from public.squad_invites where squad_id = v_squad and invited = v_target and status = 'pending') then
    return jsonb_build_object('ok', false, 'error', 'Invite already sent.'); end if;
  insert into public.squad_invites (squad_id, invited, invited_by) values (v_squad, v_target, v_uid);
  return jsonb_build_object('ok', true);
end $function$

squad_invite_respond:
CREATE OR REPLACE FUNCTION public.squad_invite_respond(p_id bigint, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_inv public.squad_invites; v_count int;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select * into v_inv from public.squad_invites where id = p_id and invited = v_uid and status = 'pending';
  if v_inv.id is null then return jsonb_build_object('ok', false, 'error', 'Invite not found or already answered.'); end if;
  if not p_accept then
    update public.squad_invites set status = 'declined' where id = p_id;
    return jsonb_build_object('ok', true, 'accepted', false);
  end if;
  if exists (select 1 from public.squad_members where user_id = v_uid) then
    return jsonb_build_object('ok', false, 'error', 'You are already in a squad. Leave it first.');
  end if;
  select count(*) into v_count from public.squad_members where squad_id = v_inv.squad_id;
  if v_count >= 6 then return jsonb_build_object('ok', false, 'error', 'That squad is full now.'); end if;
  insert into public.squad_members (squad_id, user_id, role) values (v_inv.squad_id, v_uid, 'member');
  update public.squad_invites set status = 'accepted' where id = p_id;
  update public.squad_invites set status = 'declined' where invited = v_uid and status = 'pending';
  return jsonb_build_object('ok', true, 'accepted', true);
end $function$

my_squad_rank:
CREATE OR REPLACE FUNCTION public.my_squad_rank()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_name text; v_board jsonb; v_row jsonb; v_rank int := 0; v_i int;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select s.name into v_name from public.squad_members m join public.squads s on s.id = m.squad_id where m.user_id = v_uid;
  if v_name is null then return jsonb_build_object('ok', false, 'error', 'Not in a squad.'); end if;
  v_board := public.squad_battle_board()->'rows';
  if v_board is null then return jsonb_build_object('ok', true, 'rank', null); end if;
  for v_i in 0..jsonb_array_length(v_board)-1 loop
    v_row := v_board->v_i;
    if v_row->>'squad' = v_name then v_rank := v_i + 1; exit; end if;
  end loop;
  return jsonb_build_object('ok', true, 'rank', nullif(v_rank,0), 'row', case when v_rank > 0 then v_row else null end, 'total', jsonb_array_length(v_board));
end $function$

admin_undo_auto:
CREATE OR REPLACE FUNCTION public.admin_undo_auto(p_queue text, p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_proof public.result_proofs; v_req public.squad_creator_requests; v_squad int;
begin
  if not (select is_admin()) then return jsonb_build_object('ok', false, 'error', 'Admin only.'); end if;
  if p_queue = 'proof' then
    select * into v_proof from public.result_proofs where id = p_id and status = 'approved' and admin_note like 'auto-approved%';
    if v_proof.id is null then return jsonb_build_object('ok', false, 'error', 'Not an auto-approved proof (or already changed).'); end if;
    update public.result_proofs set status = 'pending', points = 0, admin_note = 'owner-undo: auto-approval reversed, back in queue', handled_at = null where id = p_id;
    update public.player_game_stats set xp = greatest(0, xp - v_proof.points), updated_at = now() where user_id = v_proof.user_id;
    insert into public.points_ledger (user_id, delta, kind, meta) values (v_proof.user_id, -v_proof.points, 'award', jsonb_build_object('undo_proof', p_id));
  elsif p_queue = 'feed' then
    update public.feed_posts set status = 'pending', ai_reason = 'owner-undo: auto-approval reversed, back in queue' where id = p_id and status = 'approved';
    if not found then return jsonb_build_object('ok', false, 'error', 'Post not in approved state.'); end if;
  elsif p_queue = 'story' then
    update public.stories set status = 'pending', ai_reason = 'owner-undo: auto-approval reversed, back in queue' where id = p_id and status = 'approved';
    if not found then return jsonb_build_object('ok', false, 'error', 'Story not in approved state.'); end if;
  elsif p_queue = 'report' then
    update public.cheat_reports set status = 'open', admin_note = 'owner-undo: auto-dismiss reversed, back in queue', handled_at = null where id = p_id and status = 'dismissed';
    if not found then return jsonb_build_object('ok', false, 'error', 'Report not in dismissed state.'); end if;
  elsif p_queue = 'creator' then
    select * into v_req from public.squad_creator_requests where id = p_id and status = 'approved';
    if v_req.id is null then return jsonb_build_object('ok', false, 'error', 'Request not in approved state.'); end if;
    select count(*) into v_squad from public.squads where captain = v_req.user_id;
    if v_squad > 0 then return jsonb_build_object('ok', false, 'error', 'They already created a squad - revoke the creator from the Squads tab instead.'); end if;
    delete from public.squad_creators where user_id = v_req.user_id;
    update public.squad_creator_requests set status = 'pending', reviewed_at = null, note = 'owner-undo: auto-approval reversed, back in queue' where id = p_id;
  elsif p_queue = 'lfg' then
    update public.lfg_lobbies set status = 'open' where id = p_id and status = 'closed';
    if not found then return jsonb_build_object('ok', false, 'error', 'Lobby not in closed state.'); end if;
  else
    return jsonb_build_object('ok', false, 'error', 'Unknown queue.');
  end if;
  insert into public.audit_log (actor, action, details) values ('owner', 'undo_auto', jsonb_build_object('queue', p_queue, 'id', p_id));
  return jsonb_build_object('ok', true);
end $function$

squad_war_challenge:
CREATE OR REPLACE FUNCTION public.squad_war_challenge(p_opponent uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_my uuid;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select id into v_my from public.squads where captain = v_uid;
  if v_my is null then return jsonb_build_object('ok', false, 'error', 'Only a squad captain can challenge.'); end if;
  if v_my = p_opponent then return jsonb_build_object('ok', false, 'error', 'Pick another squad.'); end if;
  if not exists (select 1 from public.squads where id = p_opponent) then return jsonb_build_object('ok', false, 'error', 'Squad not found.'); end if;
  if exists (select 1 from public.squad_wars where status in ('pending','accepted','scheduled') and
      ((challenger_id = v_my and opponent_id = p_opponent) or (challenger_id = p_opponent and opponent_id = v_my))) then
    return jsonb_build_object('ok', false, 'error', 'There is already a live war between these squads.');
  end if;
  insert into public.squad_wars (challenger_id, opponent_id, result) values (v_my, p_opponent, nullif(p_note,''));
  return jsonb_build_object('ok', true);
end $function$

