end $function$

admin_war_update:
CREATE OR REPLACE FUNCTION public.admin_war_update(p_war bigint, p_action text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_winner uuid DEFAULT NULL::uuid, p_result text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_w public.squad_wars; m record;
begin
  if not (select is_admin()) then return jsonb_build_object('ok', false, 'error', 'Admin only.'); end if;
  select * into v_w from public.squad_wars where id = p_war;
  if v_w.id is null then return jsonb_build_object('ok', false, 'error', 'War not found.'); end if;
  if p_action = 'schedule' then
    update public.squad_wars set status = 'scheduled', scheduled_at = p_scheduled_at, updated_at = now() where id = p_war;
  elsif p_action = 'result' then
    if p_winner is not null and p_winner <> v_w.challenger_id and p_winner <> v_w.opponent_id then
      return jsonb_build_object('ok', false, 'error', 'Winner must be one of the two squads (or empty for a draw).');
    end if;
    update public.squad_wars set status = 'done', winner_id = p_winner, result = p_result, updated_at = now() where id = p_war;
    if p_winner is not null then
      for m in select user_id from public.squad_members where squad_id = p_winner loop
        perform public.award_xp(m.user_id, 'match', 25, jsonb_build_object('war', p_war));
      end loop;
    end if;
  elsif p_action = 'cancel' then
    update public.squad_wars set status = 'cancelled', updated_at = now() where id = p_war;
  else
    return jsonb_build_object('ok', false, 'error', 'Bad action.');
  end if;
  return jsonb_build_object('ok', true);
end $function$

room_feed:
CREATE OR REPLACE FUNCTION public.room_feed(p_after bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_squad uuid;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select squad_id into v_squad from public.squad_members where user_id = v_uid;
  if v_squad is null then return jsonb_build_object('ok', false, 'error', 'no_squad'); end if;
  return jsonb_build_object('ok', true, 'squad', v_squad, 'rows', coalesce((
    select jsonb_agg(t) from (
      select m.id, m.body, m.created_at, m.user_id,
             coalesce(pr.ign, pr.username, 'player') as by
      from public.squad_room_messages m
      left join public.profiles pr on pr.id = m.user_id
      where m.squad_id = v_squad and m.id > p_after
      order by m.id asc limit 100
    ) t), '[]'::jsonb));
end $function$

predict_bracket:
CREATE OR REPLACE FUNCTION public.predict_bracket(p_match bigint, p_pick text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_m public.bracket_matches;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  if p_pick is null or p_pick not in ('a','b') then return jsonb_build_object('ok', false, 'error', 'Pick a team.'); end if;
  select * into v_m from public.bracket_matches where id = p_match for update;
  if v_m.id is null then return jsonb_build_object('ok', false, 'error', 'Match not found.'); end if;
  if v_m.winner is not null then return jsonb_build_object('ok', false, 'error', 'This match already has a result.'); end if;
  if v_m.starts_at is null then return jsonb_build_object('ok',false,'error','Predictions open after a start time is set.'); end if;
  if nullif(trim(v_m.squad_a),'') is null or nullif(trim(v_m.squad_b),'') is null then return jsonb_build_object('ok',false,'error','Both squads must be announced first.'); end if;
  if now() >= v_m.starts_at then
    return jsonb_build_object('ok', false, 'error', 'Predictions are locked - the match has started.');
  end if;
  insert into public.bracket_predictions (match_id, user_id, pick) values (p_match, v_uid, p_pick)
    on conflict (match_id, user_id) do update set pick = excluded.pick, created_at = now();
  return jsonb_build_object('ok', true, 'pick', p_pick);
end $function$

claim_champion_title:
CREATE OR REPLACE FUNCTION public.claim_champion_title(p_tournament text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_final record; v_squad_id uuid; v_badge text;
begin
  if v_uid is null then return jsonb_build_object('ok',false,'error','Login required.'); end if;
  select m.* into v_final from public.bracket_matches m
   where m.tournament_id = p_tournament and m.winner is not null
     and m.round = (select max(round) from public.bracket_matches where tournament_id = p_tournament)
   order by m.position limit 1;
  if v_final is null then return jsonb_build_object('ok',false,'error','No champion has been decided yet.'); end if;
  select s.id into v_squad_id from public.squads s join public.squad_members sm on sm.squad_id = s.id
   where sm.user_id = v_uid and upper(s.name) = upper(v_final.winner) limit 1;
  if v_squad_id is null then return jsonb_build_object('ok',false,'error','Only the champion squad can claim this title.'); end if;
  v_badge := 'Champion: ' || coalesce((select name from public.tournaments where id = p_tournament), p_tournament);
  insert into public.badges (user_id, badge) values (v_uid, v_badge) on conflict do nothing;
  insert into public.audit_log (actor, action, details) values (v_uid, 'claim_champion_title', jsonb_build_object('tournament', p_tournament, 'winner', v_final.winner)::text);
  return jsonb_build_object('ok',true,'badge',v_badge);
end $function$

