push_dispatch:
CREATE OR REPLACE FUNCTION public.push_dispatch()
 RETURNS TABLE(user_id uuid, kind text, title text, body text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
declare
  u record; r record;
  v_squad uuid; v_squad_name text; v_now timestamptz := now();
begin
  insert into public.push_dispatch_state (user_id)
  select distinct dt.user_id from public.device_tokens dt
  where dt.user_id is not null
    and not exists (select 1 from public.push_dispatch_state x where x.user_id = dt.user_id);

  for u in select ds.* from public.push_dispatch_state ds
    where exists (select 1 from public.device_tokens dt where dt.user_id = ds.user_id)
  loop
    if not u.baseline_done then
      update public.push_dispatch_state ds2 set
        since_notif = coalesce((select max(n.id) from public.notifications n where n.user_id = u.user_id), -1),
        since_dm = v_now, since_room = v_now, since_tourn = v_now,
        baseline_done = true, updated_at = v_now
      where ds2.user_id = u.user_id;
      continue;
    end if;

    for r in select n.id, n.title as n_title, n.body as n_body from public.notifications n
      where n.user_id = u.user_id and n.id > u.since_notif order by n.id asc limit 10
    loop
      user_id := u.user_id; kind := 'notification'; title := r.n_title; body := r.n_body; return next;
      update public.push_dispatch_state ds2 set since_notif = greatest(ds2.since_notif, r.id) where ds2.user_id = u.user_id;
    end loop;

    for r in select coalesce(pr.ign, pr.username, 'player') as sender_name, count(*)::int as c
      from public.dm_messages m
      join public.dm_threads th on th.id = m.thread_id
      left join public.profiles pr on pr.id = m.sender_id
      where (th.user_a = u.user_id or th.user_b = u.user_id)
        and m.sender_id <> u.user_id and m.created_at > u.since_dm
      group by 1 limit 10
    loop
      user_id := u.user_id; kind := 'dm'; title := r.sender_name;
      body := case when r.c > 1 then r.c || ' new encrypted messages - open XARENA to read'
                   else 'New encrypted message - open XARENA to read' end;
      return next;
    end loop;

    select sm.squad_id into v_squad from public.squad_members sm where sm.user_id = u.user_id;
    if v_squad is not null then
      select sq.name into v_squad_name from public.squads sq where sq.id = v_squad;
      for r in select left(m.body, 80) as m_body, coalesce(pr.ign, pr.username, 'player') as sender_name
        from public.squad_room_messages m
        left join public.profiles pr on pr.id = m.user_id
        where m.squad_id = v_squad and m.user_id <> u.user_id and m.created_at > u.since_room
        order by m.id asc limit 10
      loop
        user_id := u.user_id; kind := 'room';
        title := r.sender_name || ' in ' || coalesce(v_squad_name, 'your clan');
        body := coalesce(nullif(r.m_body, ''), 'New clan room message');
        return next;
      end loop;
    end if;

    for r in select t.name as t_name, t.date_text as t_date from public.tournaments t
      where t.status = 'upcoming' and t.created_at > u.since_tourn order by t.created_at asc limit 5
    loop
      user_id := u.user_id; kind := 'tournament';
      title := 'New tournament: ' || r.t_name;
      body := coalesce(r.t_date, 'Dates revealed soon');
      return next;
    end loop;

    update public.push_dispatch_state ds2 set since_dm = v_now, since_room = v_now, since_tourn = v_now, updated_at = v_now
    where ds2.user_id = u.user_id;
  end loop;
end $function$

scrim_reach:
CREATE OR REPLACE FUNCTION public.scrim_reach(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid := auth.uid(); r scrim_requests%rowtype; mine squads%rowtype; theirs text;
begin
  if u is null then return jsonb_build_object('ok',false,'error','Log in first.'); end if;
  select * into mine from squads where captain=u; if mine.id is null then return jsonb_build_object('ok',false,'error','Only a squad captain can reply.'); end if;
  select * into r from scrim_requests where id=p_id and status='open' and expires_at>now(); if r.id is null then return jsonb_build_object('ok',false,'error','Request not available.'); end if;
  if r.squad_id=mine.id then return jsonb_build_object('ok',false,'error','That is your own request.'); end if;
  perform notify(r.user_id,'scrim',mine.name||' wants to scrim','They replied to your '||r.day_text||' scrim request. Message their captain in XARENA Messages.','messages.html','scrim:'||p_id||':'||mine.id);
  return jsonb_build_object('ok',true,'captain',(select username from profiles where id=mine.captain));
end $function$

scrim_post:
CREATE OR REPLACE FUNCTION public.scrim_post(p_day text, p_time text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid := auth.uid(); sq squads%rowtype; mp profiles%rowtype; v uuid;
begin
  if u is null then return jsonb_build_object('ok',false,'error','Log in first.'); end if;
  select * into sq from squads where captain=u; if sq.id is null then return jsonb_build_object('ok',false,'error','Only a squad captain can post a scrim request.'); end if;
  select * into mp from profiles where id=u;
  if mp.geo_district is null then return jsonb_build_object('ok',false,'error','location_required'); end if;
  if (select count(*) from scrim_requests where squad_id=sq.id and status='open' and expires_at>now()) >= 2 then return jsonb_build_object('ok',false,'error','You already have 2 open scrim requests.'); end if;
  insert into scrim_requests(squad_id,user_id,state,district,day_text,time_text,note) values (sq.id,u,mp.geo_state,mp.geo_district,left(coalesce(p_day,'Tonight'),30),left(coalesce(p_time,''),30),left(coalesce(p_note,''),160)) returning id into v;
  return jsonb_build_object('ok',true,'id',v);
end $function$

scrim_find:
CREATE OR REPLACE FUNCTION public.scrim_find()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid := auth.uid(); mp profiles%rowtype;
begin
  if u is null then return jsonb_build_object('ok',false,'error','Log in first.'); end if;
  select * into mp from profiles where id=u; if mp.geo_district is null then return jsonb_build_object('ok',false,'error','location_required'); end if;
  return jsonb_build_object('ok',true,'district',mp.geo_district,'rows',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'squad',s.name,'tag',s.tag,'day',r.day_text,'time',r.time_text,'note',r.note,'mine',r.user_id=u) order by r.created_at desc)
    from scrim_requests r join squads s on s.id=r.squad_id where r.status='open' and r.expires_at>now() and r.district=mp.geo_district and r.state=mp.geo_state),'[]'::jsonb));
end $function$

city_squad_create:
CREATE OR REPLACE FUNCTION public.city_squad_create(p_name text, p_city text, p_state text, p_desc text, p_slots integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v uuid := auth.uid(); nid bigint;
begin
  if v is null or not exists(select 1 from creators where user_id=v and active) then return jsonb_build_object('ok',false,'error','Creators only.'); end if;
  if (select count(*) from city_squads where creator=v and status='open')>=2 then return jsonb_build_object('ok',false,'error','You can have 2 open city squads.'); end if;
  insert into city_squads(creator,name,city,state,description,slots) values (v,btrim(p_name),btrim(p_city),nullif(btrim(coalesce(p_state,'')),''),nullif(btrim(coalesce(p_desc,'')),''),coalesce(p_slots,4)) returning id into nid;
  return jsonb_build_object('ok',true,'id',nid);
exception when check_violation then return jsonb_build_object('ok',false,'error','Check name (3-40), city and slots (1-50). No money wording.');
  when others then return jsonb_build_object('ok',false,'error',sqlerrm);
end $function$

city_squad_apply:
CREATE OR REPLACE FUNCTION public.city_squad_apply(p_squad bigint, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v uuid := auth.uid(); s record;
begin
  if v is null then return jsonb_build_object('ok',false,'error','Log in first.'); end if;
  select * into s from city_squads where id=p_squad;
  if s.id is null or s.status<>'open' then return jsonb_build_object('ok',false,'error','This squad is closed.'); end if;
  if s.creator=v then return jsonb_build_object('ok',false,'error','You are the host.'); end if;
  if exists(select 1 from profiles where id=v and banned) then return jsonb_build_object('ok',false,'error','Account restricted.'); end if;
  if (select count(*) from city_squad_applications where user_id=v and created_at>now()-interval '24 hours')>=5 then return jsonb_build_object('ok',false,'error','Limit: 5 applications per day.'); end if;
  insert into city_squad_applications(squad_id,user_id,note) values (p_squad,v,left(coalesce(p_note,''),200))
   on conflict (squad_id,user_id) do update set status='pending', note=excluded.note where city_squad_applications.status in ('withdrawn','rejected');
  return jsonb_build_object('ok',true,'status','pending');
exception when others then return jsonb_build_object('ok',false,'error','No money wording or phone numbers in the note.');
end $function$

city_squad_decide:
CREATE OR REPLACE FUNCTION public.city_squad_decide(p_app bigint, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a record; s record; n int;
begin
  select * into a from city_squad_applications where id=p_app; select * into s from city_squads where id=a.squad_id;
  if a.id is null or s.creator<>auth.uid() then return jsonb_build_object('ok',false,'error','Host only.'); end if;
  if p_accept then select count(*) into n from city_squad_applications where squad_id=s.id and status='accepted';
    if n>=s.slots then return jsonb_build_object('ok',false,'error','Squad is full.'); end if; end if;
  update city_squad_applications set status=case when p_accept then 'accepted' else 'rejected' end where id=p_app;
  return jsonb_build_object('ok',true);
end $function$

squad_profile:
CREATE OR REPLACE FUNCTION public.squad_profile(p_squad uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s squads%rowtype; rec jsonb; mem jsonb;
begin
  select * into s from squads where id=p_squad; if not found then return jsonb_build_object('ok',false); end if;
  select coalesce(jsonb_agg(jsonb_build_object('ign',coalesce(p.ign,p.username),'role',m.role,'avatar_url',p.avatar_url) order by m.joined_at),'[]'::jsonb)
    into mem from squad_members m join profiles p on p.id=m.user_id where m.squad_id=p_squad;
  select jsonb_build_object('matches',count(distinct e.match_id),'kills',coalesce(sum(e.kills),0),'points',coalesce(sum(e.points),0),'best_place',min(e.placement))
    into rec from lb_entries e where lower(trim(e.squad))=lower(trim(s.name));
  return jsonb_build_object('ok',true,'id',s.id,'name',s.name,'tag',s.tag,'bio',s.bio,'logo_url',s.logo_url,'members',mem,'record',rec,
    'tournaments',(select coalesce(jsonb_agg(distinct r.tournament_id),'[]'::jsonb) from registrations r where lower(trim(r.squad))=lower(trim(s.name)) and r.status not in ('rejected','cancelled','declined')));
end $function$

match_room:
CREATE OR REPLACE FUNCTION public.match_room(p_match uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_m public.matches; v_reg boolean;
begin
  if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Log in first.'); end if;
  select * into v_m from public.matches where id = p_match;
  if v_m.id is null then return jsonb_build_object('ok', false, 'error', 'Match not found.'); end if;
  if v_m.room_id is null then return jsonb_build_object('ok', false, 'error', 'Room details are not posted yet.'); end if;
  if v_m.starts_at is not null and now() < v_m.starts_at - make_interval(mins => v_m.reveal_minutes) then
    return jsonb_build_object('ok', false, 'error', 'Room ID unlocks ' || v_m.reveal_minutes || ' minutes before the match (' || to_char(v_m.starts_at at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST start).');
  end if;
  select exists (select 1 from public.registrations r where r.tournament_id = v_m.tournament_id and r.status not in ('rejected','cancelled','declined','waitlist') and r.user_id is not null and (r.user_id = v_uid or r.user_id in (select sm2.user_id from public.squad_members sm1 join public.squad_members sm2 on sm2.squad_id = sm1.squad_id where sm1.user_id = v_uid))) into v_reg;
  if not v_reg then return jsonb_build_object('ok', false, 'error', 'Room details are for registered players of this tournament only.'); end if;
  return jsonb_build_object('ok', true, 'room_id', v_m.room_id, 'room_pass', v_m.room_pass, 'title', v_m.title, 'starts_at', v_m.starts_at);
end $function$
